<template><div class="page"><div class="head"><div><h2>教学案例库</h2><p>案例版本、同行评审和公开状态管理</p></div><div class="head-actions"><el-button @click="downloadTemplate">下载导入模板</el-button><el-button :loading="importing" @click="chooseImport">模板导入</el-button><input ref="importInput" class="hidden-input" type="file" accept=".csv,text/csv" @change="readImportFile"><el-button type="primary" @click="newCase">新建案例</el-button></div></div>
  <el-dialog v-model="importVisible" title="模板导入预览" width="min(1000px, 94vw)"><p>校验通过后将一次性创建草稿，不会发布。每次最多导入 100 条；案例类型留空时默认为“教学型”，多个方法或主题标签请用分号分隔。作品、授权、指导手册和附件请在创建后补充。</p><el-table :data="importRows" max-height="50vh" size="small"><el-table-column prop="line" label="行号" width="70"/><el-table-column prop="title" label="案例标题" min-width="160"/><el-table-column prop="course_name" label="所属课程" min-width="140"/><el-table-column label="校验结果" min-width="220"><template #default="{row}"><el-tag v-if="row.errors.length" type="danger">{{ row.errors.join('；') }}</el-tag><el-tag v-else type="success">可导入</el-tag></template></el-table-column></el-table><p v-if="importRows.length" class="import-summary">共 {{ importRows.length }} 条，{{ importRows.filter(row => !row.errors.length).length }} 条通过，{{ importRows.filter(row => row.errors.length).length }} 条有问题。全部通过后才能导入。</p><template #footer><el-button @click="importVisible=false">取消</el-button><el-button type="primary" :disabled="!importRows.length || importRows.some(row => row.errors.length)" :loading="importing" @click="submitImport">确认创建草稿</el-button></template></el-dialog>
  <el-form inline class="filters" @submit.prevent="refresh"><el-form-item label="关键词"><el-input v-model="keyword" placeholder="编号或标题" clearable/></el-form-item><el-form-item label="案例状态"><el-select v-model="status" clearable placeholder="全部"><el-option label="草稿" value="draft"/><el-option label="待审核" value="pending_review"/><el-option label="已通过" value="approved"/><el-option label="已发布" value="published"/><el-option label="已归档" value="retired"/></el-select></el-form-item><el-button @click="refresh">筛选</el-button></el-form>
  <el-table :data="rows" v-loading="loading" stripe><el-table-column prop="case_code" label="案例编号" width="150"/><el-table-column prop="title" label="标题" min-width="200"/><el-table-column prop="course_name" label="课程"/><el-table-column prop="review_status" label="版本审核"/><el-table-column prop="status" label="状态"/><el-table-column label="两年复审"><template #default="{row}"><el-tag v-if="reviewDue(row)" type="warning">需复审</el-tag><span v-else>{{ row.last_reviewed_at || '未发布' }}</span></template></el-table-column><el-table-column label="操作" width="230"><template #default="{row}"><el-button link type="primary" @click="edit(row.case_code)">编辑</el-button><el-button link @click="workflow(row.case_code,'submit')">提交评审</el-button><el-button link type="success" @click="workflow(row.case_code,'publish',row.is_featured)">发布</el-button></template></el-table-column></el-table>
  <el-dialog v-model="visible" :title="form.case_code ? `编辑 ${form.case_code}` : '新建教学案例'" width="min(920px, 94vw)" top="4vh"><el-form label-width="120px" class="editor"><div class="form-grid"><el-form-item label="案例标题"><el-input v-model="form.title" maxlength="20" show-word-limit/></el-form-item><el-form-item label="案例类型"><el-select v-model="form.case_type"><el-option label="教学型" value="教学型"/><el-option label="工作型" value="工作型"/><el-option label="混合型" value="混合型"/></el-select></el-form-item><el-form-item label="所属课程"><el-input v-model="form.course_name"/></el-form-item><el-form-item label="课程模块"><el-input v-model="form.course_module"/></el-form-item><el-form-item label="年级"><el-input v-model="form.grade_year"/></el-form-item><el-form-item label="课题"><el-input v-model="form.topic_name"/></el-form-item><el-form-item label="项目时间"><el-input v-model="form.project_time"/></el-form-item><el-form-item label="适用对象"><el-input v-model="form.target_audience"/></el-form-item></div><el-form-item label="重点案例"><el-switch v-model="form.is_featured" active-text="设为编辑精选"/></el-form-item><el-form-item label="案例导读"><el-input v-model="form.introduction" type="textarea" :rows="3"/></el-form-item><el-form-item label="课题任务"><el-input v-model="form.assignment" type="textarea" :rows="3"/></el-form-item><el-form-item label="核心问题"><el-input v-model="form.problem" type="textarea" :rows="3"/></el-form-item><el-form-item label="案例正文"><el-input v-model="form.case_body" type="textarea" :rows="8" placeholder="支持 Markdown；发布需满足模板规定的正文长度"/></el-form-item><el-form-item label="教学启示"><el-input v-model="form.teaching_takeaways" type="textarea" :rows="4"/></el-form-item><el-form-item label="公开状态"><el-select v-model="form.permission_status"><el-option label="待核实" value="pending"/><el-option label="公开" value="public"/><el-option label="校内" value="campus"/><el-option label="课堂使用" value="classroom"/></el-select></el-form-item><el-form-item label="相似度 (%)"><el-input-number v-model="form.plagiarism_rate" :min="0" :max="100" :precision="2"/></el-form-item><el-form-item label="扩展元数据"><el-input v-model="metadataText" type="textarea" :rows="5" placeholder="JSON：chineseAbstract、englishAbstract、chineseKeywords、englishKeywords、publicAuthors、citation、publicReferences、similarityException"/></el-form-item><el-form-item label="标签"><el-input v-model="tagsText" type="textarea" :rows="3" placeholder="JSON，例如 {&quot;method&quot;:[&quot;材料转译&quot;],&quot;theme&quot;:[&quot;传统文化&quot;]}"/></el-form-item><el-form-item label="作品条目"><el-input v-model="worksText" type="textarea" :rows="5" placeholder="JSON 数组：title、author_name、author_statement、medium、description、display_allowed；必须有作品授权才能勾选公开"/></el-form-item><el-form-item label="教师指导手册"><el-input v-model="guideText" type="textarea" :rows="6" placeholder="JSON：objectives、preparation、workflow、discussion、assessment、downloadUrl"/></el-form-item><el-form-item v-if="form.case_code" label="相似度说明"><el-input v-model="similarityException" placeholder="相似度高于 15% 时，填写机构核验依据"/></el-form-item><el-form-item v-if="form.case_code" label="评审记录"><div class="review-row"><el-input v-model="reviewer" placeholder="评审专家代号"/><el-select v-model="decision"><el-option label="通过" value="approve"/><el-option label="修改" value="revise"/><el-option label="拒绝" value="reject"/></el-select><el-input v-model="reviewComments" placeholder="评审意见"/><el-button @click="saveReview">记录评审</el-button></div><p>当前版本已通过 {{ form.reviews?.filter((r:any)=>r.decision==='approve').length || 0 }} 位评审</p></el-form-item><el-form-item v-if="form.case_code" label="附件"><div class="asset-form"><input type="file" @change="assetFile=($event.target as HTMLInputElement).files?.[0] || null"><el-select v-model="assetWork"><el-option label="案例公共附件" value=""/><el-option v-for="work in form.works || []" :key="work.id" :label="`作品：${work.title}`" :value="String(work.id)"/></el-select><el-select v-model="assetVisibility"><el-option label="内部审核" value="internal"/><el-option label="教师可见" value="teacher"/><el-option label="课堂授权" value="classroom"/><el-option label="公开展示" value="public"/></el-select><el-select v-model="assetRights"><el-option label="授权待核实" value="pending"/><el-option label="已确认授权" value="confirmed"/><el-option label="限制使用" value="restricted"/></el-select><el-input v-model="assetSource" placeholder="来源与授权依据"/><el-button :disabled="!assetFile" @click="uploadAsset">上传到当前草稿</el-button></div><p>未确认授权的附件不会对外提供；作品附件还需在作品条目中勾选 display_allowed。</p></el-form-item></el-form><template #footer><el-button @click="visible=false">关闭</el-button><el-button type="primary" :loading="saving" @click="save">保存草稿</el-button><el-button v-if="form.case_code" type="success" @click="publishCurrent">发布当前版本</el-button></template></el-dialog>
</div></template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { caseAdminApi } from '../../api'
const rows=ref<any[]>([]),loading=ref(false),saving=ref(false),visible=ref(false),metadataText=ref('{}'),tagsText=ref('{}'),worksText=ref('[]'),guideText=ref('{}'),reviewer=ref(''),reviewComments=ref(''),decision=ref('approve'),similarityException=ref(''),keyword=ref(''),status=ref('')
const assetFile=ref<File|null>(null),assetWork=ref(''),assetVisibility=ref('internal'),assetRights=ref('pending'),assetSource=ref('')
const importInput=ref<HTMLInputElement|null>(null),importVisible=ref(false),importing=ref(false),importRows=ref<any[]>([])
const importHeaders=['案例标题','案例类型','所属课程','课程模块','年级','课题','项目时间','适用对象','案例导读','课题任务','核心问题','案例正文','教学启示','方法标签','主题标签']
function downloadTemplate(){const csv='\uFEFF'+importHeaders.join(',')+'\r\n';const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='教学案例批量导入模板.csv';link.click();URL.revokeObjectURL(url)}
function chooseImport(){if(importInput.value){importInput.value.value='';importInput.value.click()}}
function parseCsv(text:string){const rows:string[][]=[];let row:string[]=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const char=text[i];if(quoted){if(char==='"'&&text[i+1]==='"'){cell+='"';i++}else if(char==='"')quoted=false;else cell+=char}else if(char==='"'){quoted=true}else if(char===','){row.push(cell);cell=''}else if(char==='\n'){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell=''}else cell+=char}if(quoted)throw new Error('CSV 引号未闭合');if(cell.length||row.length){row.push(cell.replace(/\r$/,''));rows.push(row)}return rows}
async function readImportFile(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;try{if(!file.name.toLowerCase().endsWith('.csv'))throw new Error('请选择 CSV 模板文件');const rows=parseCsv((await file.text()).replace(/^\uFEFF/,''));const header=rows.shift()?.map(value=>value.trim())||[];if(importHeaders.some(value=>!header.includes(value)))throw new Error('表头与模板不一致，请重新下载模板');const positions=importHeaders.map(value=>header.indexOf(value));const values=rows.map((cells,index)=>({line:index+2,values:Object.fromEntries(importHeaders.map((key,i)=>[key,cells[positions[i]]||'']))})).filter(row=>Object.values(row.values).some(value=>String(value).trim()));if(!values.length)throw new Error('模板中没有可导入的数据');if(values.length>100)throw new Error('每次最多导入 100 条');const seen=new Set<string>();importRows.value=values.map(({line,values})=>{const title=String(values['案例标题']).trim(),course=String(values['所属课程']).trim(),type=String(values['案例类型']).trim()||'教学型',errors:string[]=[];if(!title)errors.push('标题必填');if([...title].length>20)errors.push('标题超过 20 字');if(!['教学型','工作型','混合型'].includes(type))errors.push('案例类型无效');const key=`${course}\u0000${title}`;if(title&&seen.has(key))errors.push('文件内标题与课程重复');if(title)seen.add(key);return{line,title,course_name:course,errors,input:{title,case_type:type,course_name:course,course_module:values['课程模块'],grade_year:values['年级'],topic_name:values['课题'],project_time:values['项目时间'],target_audience:values['适用对象'],introduction:values['案例导读'],assignment:values['课题任务'],problem:values['核心问题'],case_body:values['案例正文'],teaching_takeaways:values['教学启示'],method_tags:String(values['方法标签']).split(/[;；]/).map(value=>value.trim()).filter(Boolean),theme_tags:String(values['主题标签']).split(/[;；]/).map(value=>value.trim()).filter(Boolean)}}});importVisible.value=true}catch(e:any){ElMessage.error(e.message||'读取模板失败')}finally{input.value=''}}
async function submitImport(){importing.value=true;try{const result=await caseAdminApi.importDrafts(importRows.value.map(row=>row.input));ElMessage.success(`已创建 ${result.cases.length} 条案例草稿`);importVisible.value=false;await refresh()}catch(e:any){ElMessage.error(e.response?.data?.message||e.message||'导入失败')}finally{importing.value=false}}
const blank=()=>({case_code:'',is_featured:false,program_code:'VC',case_year:new Date().getFullYear(),title:'',case_type:'教学型',course_name:'',course_module:'',grade_year:'',topic_name:'',project_time:'',target_audience:'',introduction:'',assignment:'',problem:'',case_body:'',teaching_takeaways:'',permission_status:'pending',plagiarism_rate:null as number|null,reviews:[] as any[]})
const form=reactive<any>(blank())
async function refresh(){loading.value=true;try{rows.value=(await caseAdminApi.list({pageSize:100,keyword:keyword.value,status:status.value})).list}finally{loading.value=false}}
function newCase(){Object.assign(form,blank());metadataText.value='{}';tagsText.value='{}';worksText.value='[]';guideText.value='{}';visible.value=true}
async function edit(code:string){try{const x=await caseAdminApi.get(code);Object.assign(form,{...blank(),...x,plagiarism_rate:x.plagiarism_rate==null?null:Number(x.plagiarism_rate)*100});metadataText.value=JSON.stringify(x.metadata||{},null,2);tagsText.value=JSON.stringify(x.tags||{},null,2);worksText.value=JSON.stringify((x.works||[]).map(({id,version_id,assets,...w}:any)=>w),null,2);guideText.value=JSON.stringify(x.teacher_guide||{},null,2);similarityException.value=x.metadata?.similarityException||'';visible.value=true}catch(e:any){ElMessage.error(e.response?.data?.message||'读取失败')}}
function parse(text:string){return JSON.parse(text)}
function reviewDue(row:any){if(!row.last_reviewed_at||row.status!=='published')return false;const reviewed=new Date(row.last_reviewed_at);return Date.now()-reviewed.getTime()>=2*365*24*60*60*1000}
async function save(){saving.value=true;try{const metadata=parse(metadataText.value);metadata.similarityException=similarityException.value;const data={...form,plagiarism_rate:form.plagiarism_rate==null?null:Number(form.plagiarism_rate)/100,metadata,tags:parse(tagsText.value),works:parse(worksText.value),teacher_guide:parse(guideText.value)};if(form.case_code)await caseAdminApi.saveDraft(form.case_code,data);else{const result=await caseAdminApi.create(data);form.case_code=result.case_code}ElMessage.success('草稿已保存');await refresh();if(form.case_code)await edit(form.case_code)}catch(e:any){ElMessage.error(e.response?.data?.message||e.message||'保存失败')}finally{saving.value=false}}
async function workflow(code:string,action:string,featured=false){try{if(action==='submit'){await caseAdminApi.submitReview(code);ElMessage.success('已提交审核')}else{await ElMessageBox.confirm('确认发布当前通过评审且满足公开条件的版本？','发布确认');await caseAdminApi.publish(code,featured);ElMessage.success('已发布')}await refresh()}catch(e:any){if(e!=='cancel')ElMessage.error(e.response?.data?.message||e.message||'操作失败')}}
async function publishCurrent(){if(!form.case_code)return;try{await ElMessageBox.confirm('确认发布此版本并保存当前精选状态？','发布确认');await caseAdminApi.publish(form.case_code,Boolean(form.is_featured));ElMessage.success('案例已发布');visible.value=false;await refresh()}catch(e:any){if(e!=='cancel')ElMessage.error(e.response?.data?.message||e.message||'发布失败')}}
async function saveReview(){if(!form.case_code)return;try{await caseAdminApi.review(form.case_code,{reviewer_label:reviewer.value,decision:decision.value,comments:reviewComments.value});ElMessage.success('评审记录已保存');await edit(form.case_code);await refresh()}catch(e:any){ElMessage.error(e.response?.data?.message||'记录失败')}}
async function uploadAsset(){if(!form.case_code||!assetFile.value)return;try{await caseAdminApi.uploadAsset(form.case_code,assetFile.value,{work_id:assetWork.value,visibility:assetVisibility.value,rights_status:assetRights.value,source_note:assetSource.value});ElMessage.success('附件已保存到私有目录');assetFile.value=null;await edit(form.case_code)}catch(e:any){ElMessage.error(e.response?.data?.message||'附件上传失败')}}
onMounted(refresh)
</script>
<style scoped>.page{background:#fff;padding:22px}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.head h2{margin:0}.head p{font-size:13px;color:#777}.head-actions{display:flex;gap:8px;align-items:center}.hidden-input{display:none}.import-summary{font-size:13px;color:#666}.editor{max-height:70vh;overflow:auto;padding:0 12px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 12px}.review-row{display:flex;gap:8px;align-items:center}.review-row p{font-size:12px;color:#777}@media(max-width:700px){.head{align-items:flex-start;gap:12px;flex-direction:column}.head-actions{flex-wrap:wrap}.form-grid{grid-template-columns:1fr}.review-row{flex-wrap:wrap}}</style>
